let data;try{data=JSON.parse(localStorage.getItem('eodiro-v1'));if(!data?.trips?.length||!Array.isArray(data.checks)||!Array.isArray(data.customPlaces))throw Error();}catch{data=initial()}
const translations={"파리": "Paris", "서울": "Seoul", "느긋하게, 파리": "Paris, at my own pace", "여권 · 유효기간 확인": "Passport & expiry date", "항공권 · 숙소 예약": "Flights & accommodation", "여행자 보험": "Travel insurance", "eSIM 준비": "Set up an eSIM", "충전기 · 보조배터리": "Chargers & power bank", "교통 패스 확인": "Check transport passes", "편한 신발": "Comfortable shoes", "호텔 체크아웃 확인": "Confirm hotel checkout", "명소": "Sight", "숙소": "Stay", "식당": "Restaurant", "카페": "Café"};
function migrateLabels(value){if(typeof value==='string')return translations[value]||value;if(Array.isArray(value))return value.map(migrateLabels);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,migrateLabels(v)]));return value}data=migrateLabels(data);saveLater();function saveLater(){try{localStorage.setItem('eodiro-v1',JSON.stringify(data))}catch{}}
