let view='plan',mode='planning',day=0,selected=null,table=false,map=null,layers=[],position=null,watch=null,nearby=null,dragged=null,filter='all';
const $=s=>document.querySelector(s),trip=()=>data.trips[data.active],stops=()=>trip().days[day]||[],place=id=>places.find(p=>p.id===id)||data.customPlaces.find(p=>p.id===id),save=()=>{try{localStorage.setItem('eodiro-v1',JSON.stringify(data))}catch{toast('Device storage is full. Export your trip to keep a copy.')}};
const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString(AppI18n.locale==='ko'?'ko-KR':'en-US',{month:'long',day:'numeric'});
const haversine=(a,b)=>{const rad=x=>x*Math.PI/180;const t=Math.sin(rad(b.lat-a.lat)/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(rad(b.lng-a.lng)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(t),Math.sqrt(1-t))};
const navs=[['plan','calendar','Itinerary'],['courses','compass','Discover routes'],['checklist','check','Packing checklist'],['guide','headphones','Audio & stories'],['tools','tools','Travel tools']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function render(){if(map){map.remove();map=null}const tr=trip();if(day>=tr.days.length)day=0;if(!stops().some(s=>s.id===selected))selected=stops()[0]?.id;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div><div class="brand"><img src="hoppi-bunny.png" alt="" width="42" height="48">Hoppi</div><div class="subbrand">WHERE TO NEXT</div></div><div><p class="nav-label">MY TRAVEL SPACE</p><nav class="nav">${navMarkup()}</nav></div><div class="side-trip"><p class="nav-label">My trips</p>${data.trips.map((t,i)=>t.completed?'':`<button data-action="switch-trip" data-index="${i}" class="${i===data.active?'chosen':''}">${(t.destination||cities[t.city]||cities.Paris).flag} &nbsp; ${esc(t.name)}</button>`).join('')}<button data-action="new-trip">＋ New trip</button><button data-action="completed-trips">Completed trips</button></div><div class="side-note">${icon('bag')}<b>Pack a little lighter.<br>Explore a little deeper.</b>Saved on this device.<br><button data-action="export" style="padding:8px 0;text-decoration:underline">Export your trip ↗</button></div></aside><section class="workspace"><header class="topbar"><div class="crumb">My trips <b>/ &nbsp; ${esc(currentCity())}</b></div><div class="top-right"><div class="mode"><button data-action="mode" data-value="planning" class="${mode==='planning'?'active':''}">${icon('calendar')} Planning mode</button><button data-action="mode" data-value="travel" class="${mode==='travel'?'active':''}">${icon('compass')} Travel mode</button></div><div class="avatar">ME</div></div></header><nav class="mobile-nav"><button data-action="completed-trips">Completed trips</button><button data-action="trip-list">${icon('bag')} My trips</button>${navMarkup()}</nav><main>${view==='plan'&&tr.completed?completedHome():view==='plan'?planView():view==='checklist'?checkView():view==='guide'?guideView():view==='tools'?toolsView():coursesView()}</main></section></div>`;if($('#map'))initMap();if(view==='tools')updateClock();}
function navMarkup(){return navs.filter(([id])=>id!=='guide'||mode==='travel').map(([id,i,label])=>`<button data-action="nav" data-value="${id}" class="${view===id?'active':''}">${icon(i)}${id==='checklist'&&mode==='travel'?(AppI18n.locale==='ko'?'오늘의 준비물':'Day bag checklist'):label}</button>`).join('')}
function dateTabs(){return `<div class="day-tabs">${trip().days.map((_,i)=>{const d=new Date(trip().start+'T12:00:00');d.setDate(d.getDate()+i);return `<button class="day-tab ${i===day?'active':''}" data-action="day" data-index="${i}"><b>DAY ${i+1}</b>${d.getMonth()+1}.${d.getDate()}<small>${esc(destinationFor(i).flag||'')} ${esc(destinationFor(i).name||trip().city)}</small></button>`}).join('')}</div><div class="day-destination"><span>${esc(cityInfo().flag||'')} ${esc(currentCity())}</span><button class="btn small" data-action="day-destination">Set destinations by day</button></div>`}
function mapBlock(){return `<div class="panel map-panel"><div class="map-title">${icon('map')} &nbsp; Your day on the map <span id="provider-label" class="muted"></span></div><div id="map"><div class="map-failure">Loading your map…</div></div><div class="map-controls"><button data-action="map-filter" data-value="all" class="${filter==='all'?'active':''}">All stops</button><button data-action="map-filter" data-value="toilet" class="${filter==='toilet'?'active':''}">Restrooms ↗</button><button data-action="map-filter" data-value="water" class="${filter==='water'?'active':''}">Water ↗</button><button data-action="locate">${icon('pin')} My location</button></div></div>`}
function prefs(){return `<div class="panel route-box"><div class="section-title"><h3>${icon('compass')} &nbsp; Travel your way</h3><span class="pill">Preferences</span></div><div class="prefs">${[['luggage','With luggage'],['stairs','Fewer stairs'],['walk','Enjoy walking']].map(([k,l])=>`<button data-action="pref" data-value="${k}" class="pref ${data.prefs[k]?'active':''}" aria-pressed="${data.prefs[k]}">${data.prefs[k]?'✓':'＋'} ${l}</button>`).join('')}</div><p>${data.prefs.stairs||data.prefs.luggage?'Check station lifts and accessibility. Confirm step-free routes with the transport operator.':'Pick the stretches you want to walk, then open directions.'}</p><p>Dashed lines show visit order, not verified streets, journey times or accessible routes.</p></div>`}
function planView(){const tr=trip();if(mode==='travel')return travelDashboard();return `<div class="intro"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h1>${mode==='travel'?'Less planning. More being here.':'A good trip starts with a little wonder.'}</h1><p>${mode==='travel'?'Your next stop, right when you need it.':'Save your favorite places. Make each day your own.'}</p></div><button class="btn" data-action="new-trip">${icon('plus')} New trip</button></div><div class="banner"><img style="${cityInfo().country!=='FR'||!['Paris','파리'].includes(currentCity())?'display:none':''}" src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Seine_Pont_Royal_Louvre_Paris.jpg/1280px-Seine_Pont_Royal_Louvre_Paris.jpg" alt="The Seine and Louvre in Paris"><div class="banner-copy"><small>${esc(cityInfo().en)}</small><h2>${esc(tr.name)}</h2><div class="banner-info"><span>${icon('calendar')} ${fmtDate(tr.start)} — ${fmtDate(tr.end)}</span><span>${tr.days.length} days away</span></div></div><button class="btn small trip-edit" data-action="edit-trip">Edit trip ↗</button></div>${mode==='travel'?travelView():`<div class="content-grid"><div class="panel"><div class="panel-head"><h2>Your itinerary</h2><button class="btn small primary" data-action="auto-plan">✧ Automatic plan</button><button class="btn small" data-action="table">${icon(table?'calendar':'table')} ${table?'Timeline':'Table view'}</button></div>${dateTabs()}<div class="day-summary"><div><h3>${day===0&&['Paris','파리'].includes(currentCity())?'A little art, a little wandering':`Day ${day+1}, your way`}</h3><span class="muted small-text">${stops().length} places · ${dayBudget()}</span></div><span class="pill">DAY ${day+1}</span></div>${table?tableView():timeline()}<div style="padding:0 22px 20px"><button class="add-stop" data-action="add-place">＋ Add a place</button></div></div><div class="map-column">${mapBlock()}${prefs()}</div></div>`}<div class="bottom-cards"><button class="mini panel" data-action="nav" data-value="checklist"><span class="mini-icon">${icon('check')}</span><div><strong>A little prep, a lot of peace</strong><p>${data.checks.filter(c=>c.done).length}/${data.checks.length} items packed</p></div><span class="arrow">↗</span></button><button class="mini panel" data-action="nav" data-value="courses"><span class="mini-icon">${icon('compass')}</span><div><strong>A different way to explore</strong><p>Find a route that feels like you</p></div><span class="arrow">↗</span></button></div><p class="footnote">Saved on this device · Costs are sample budgets. Check official admission prices. Places: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a>. Photo: <a href="https://commons.wikimedia.org/wiki/File:Seine_Pont_Royal_Louvre_Paris.jpg" target="_blank" rel="noopener">Wolfgang Moroder / CC BY 2.5</a> (cropped)</p>`}
function stopBudget(s){const p=place(s.place),country=destinationFor(s.day??day).country;return Number.isFinite(s.budgetAmount)?{currency:s.budgetCurrency||TravelPlanner.currency(country),low:s.budgetAmount,high:s.budgetAmount,kind:'personal'}:TravelPlanner.budget(p,country)}
function money(n,c){return c?new Intl.NumberFormat(AppI18n.locale==='ko'?'ko-KR':'en-GB',{style:'currency',currency:c}).format(n):String(n)}
function budgetText(b){if(b.low===null)return AppI18n.translate('Price needs checking');return (b.kind==='estimate'?AppI18n.translate('Planning allowance')+' ':b.kind==='personal'?AppI18n.translate('Budget')+' ':AppI18n.translate('Listed admission')+' ')+money(b.low,b.currency)+(b.high!==b.low?'–'+money(b.high,b.currency):'')}
function dayBudget(){const values=stops().map(stopBudget),known=values.filter(b=>b.low!==null);if(!known.length)return AppI18n.translate('Price needs checking');const c=known[0].currency;if(known.some(b=>b.currency!==c))return AppI18n.translate('Price needs checking');const low=known.reduce((n,b)=>n+b.low,0),high=known.reduce((n,b)=>n+b.high,0);return AppI18n.translate('Known costs')+' '+money(low,c)+(low!==high?'–'+money(high,c):'')+(known.length<values.length?' + '+AppI18n.translate('Price needs checking'):'')}
function bookingLink(p){return /^https?:\/\//.test(p.website||'')?p.website:'https://www.google.com/search?q='+encodeURIComponent(p.name+' '+currentCity()+' official tickets')}
function bookingMarkup(s,p){return s.reservation?`<span class="pill orange">Reservation ${esc(s.reservation)}</span>`:p.bookingSuggested?`<a class="pill orange" href="${esc(bookingLink(p))}" target="_blank" rel="noopener">${AppI18n.translate('Suggested booking')} ${esc(s.time)} ↗</a>`:''}
function timeline(){return `<div class="timeline">${stops().length?stops().map((s,i)=>{const p=place(s.place);return `<div class="stop ${s.id===selected?'selected':''}" draggable="true" data-stop="${s.id}"><div class="number">${i+1}</div><div><div class="stop-card"><div class="stop-time">${esc(s.time)} · ${s.duration||p.duration} min stay · ${AppI18n.translate('Planned duration')}</div><div class="stop-title"><button class="stop-name" data-action="select" data-id="${s.id}">${esc(p.name)}</button><div class="move-actions"><button aria-label="${esc(p.name)} move up" data-action="move" data-index="${i}" data-delta="-1" ${i===0?'disabled':''}>↑</button><button aria-label="${esc(p.name)} move down" data-action="move" data-index="${i}" data-delta="1" ${i===stops().length-1?'disabled':''}>↓</button><button aria-label="${esc(p.name)} edit stop" data-action="edit-stop" data-id="${s.id}">⋯</button></div></div><div class="stop-meta"><span>${esc(p.type)}</span>${p.searchUrl?`<a href="${esc(p.searchUrl)}" target="_blank" rel="noopener">Browse nearby options ↗</a>`:''}${s.label&&s.label!=='Sightseeing'?`<span class="pill">${AppI18n.translate(s.label)}</span>`:''}${p.durationSource?`<a href="${esc(p.durationSource)}" target="_blank" rel="noopener">Visit duration source ↗</a>`:''}${bookingMarkup(s,p)}<span>${esc(budgetText(stopBudget(s)))}</span></div></div>${i<stops().length-1?`<div class="connector">${icon('walk')} straight-line ${(haversine(p,place(stops()[i+1].place))/1000).toFixed(1)} km <span>· check walking route</span></div>`:''}</div></div>`}).join(''):'<div class="empty">A day of possibilities.<br>Add your first place to get started.</div>'}</div>`}
function tableView(){return `<div class="table-wrap"><table><thead><tr><th>Time</th><th>Place</th><th>Reservation</th><th>Budget</th><th></th></tr></thead><tbody>${stops().map(s=>`<tr><td>${esc(s.time)}</td><td>${esc(place(s.place).name)}</td><td>${bookingMarkup(s,place(s.place))||'—'}</td><td>${esc(budgetText(stopBudget(s)))}</td><td><button data-action="edit-stop" data-id="${s.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}
function travelView(){const s=stops().find(s=>s.id===selected)||stops()[0],p=s&&place(s.place);return `<div class="content-grid travel-grid"><div>${dateTabs()}${p?`<div class="travel-hero"><span class="eyebrow">NEXT DESTINATION · DAY ${day+1}</span><h2>${esc(p.name)}</h2><p>Planned ${esc(s.time)} ${s.reservation?'· Reservation '+esc(s.reservation):''}<br>${position?'Straight-line distance: '+(haversine(position,p)/1000).toFixed(1)+' km':'Enable location to see how far your next stop is.'}</p><div class="travel-actions"><a class="btn lime" target="_blank" rel="noopener" href="${directions(p)}">${icon('arrow')} Directions</a><button class="btn" data-action="complete">Next stop</button></div></div><div class="panel page-panel"><h3 style="margin-top:0">Before you head out</h3><div class="route-step">${icon('walk')} Leave a little time to wander<small>Open directions for street routes and estimated journey times</small></div><div class="route-step">${icon('train')} ${esc(currentCity())} transit<small>Check lifts, stairs and service updates with the operator.</small><a target="_blank" rel="noopener" href="${['Seoul','서울'].includes(currentCity())?'https://www.seoulmetro.co.kr/':['Paris','파리'].includes(currentCity())?'https://www.iledefrance-mobilites.fr/en':'https://www.google.com/search?q='+encodeURIComponent(currentCity()+' official public transport tickets')}">Find transit & ticket information ↗</a></div><button class="btn" data-action="nav" data-value="guide">${icon('headphones')} The story of this place</button></div>`:'<div class="panel empty">No stops planned for this day.<br><button class="btn" data-action="add-place">Add a place</button></div>'}</div><div class="map-column">${mapBlock()}${prefs()}</div></div>`}
const directions=p=>cityInfo().country==='KR'?'https://map.naver.com/p/search/'+encodeURIComponent(p.name):`https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lng}${position?'&origin='+position.lat+','+position.lng:''}&travelmode=${data.prefs.walk&&!data.prefs.luggage?'walking':'transit'}`;
async function initMap(){const element=$('#map'),info=cityInfo();try{const result=await TravelMaps.create({element,country:info.country,center:info.center,points:stops().map(s=>({...place(s.place),id:s.id})),selected,onSelect:id=>{selected=id;render()},position});if(!element.isConnected){result?.remove();return}if(result){map=result;$('#provider-label').textContent=result.provider==='naver'?' · NAVER':' · Google';return}$('#provider-label').textContent=' · Preview map';initLeaflet()}catch(error){if(!element.isConnected)return;$('#provider-label').textContent=' · Connection issue';element.innerHTML='<div class="map-failure">'+esc(error.message)+'<br>Check your API key and allowed domains.</div>'}}
window.gm_authFailure=()=>toast('Google Maps authentication failed. Check the key and allowed domain.');window.navermap_authFailure=()=>toast('NAVER Maps authentication failed. Check the Client ID and domain.');
function initLeaflet(){if(!window.L){$('#map').innerHTML='<div class="map-failure">The map could not load.<br>Check your connection and refresh.</div>';return}$('#map').innerHTML='';map=L.map('map',{zoomControl:false}).setView([cityInfo().center.lat,cityInfo().center.lng],14);L.control.zoom({position:'bottomright'}).addTo(map);const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);let tileErrorShown=false;tiles.on('tileerror',()=>{if(!tileErrorShown){tileErrorShown=true;toast('Map tiles could not load. Check your connection.')}});const points=[];stops().forEach((s,i)=>{const p=place(s.place);points.push([p.lat,p.lng]);L.marker([p.lat,p.lng],{icon:L.divIcon({className:'map-marker '+(s.id===selected?'selected':''),html:String(i+1),iconSize:[32,32],iconAnchor:[16,16]})}).addTo(map).bindPopup(esc(p.name)).on('click',()=>{selected=s.id;render()})});if(points.length){if(points.length>1)L.polyline(points,{color:'#39715b',weight:3,dashArray:'6,9',opacity:.75}).addTo(map);map.fitBounds(L.latLngBounds(points),{padding:[65,65],maxZoom:15})}if(position)L.circleMarker([position.lat,position.lng],{radius:8,color:'white',weight:3,fillColor:'#357ddd',fillOpacity:1}).addTo(map).bindPopup('My location');setTimeout(()=>map?.invalidateSize?.(),100)}
function checklistDate(){return new Date(Date.parse(trip().start+'T12:00:00Z')+day*86400000).toISOString().slice(0,10)}
function activeChecks(){if(mode!=='travel')return data.checks;const tr=trip(),date=checklistDate();tr.dailyChecks??={};if(!tr.dailyChecks[date]){tr.dailyChecks[date]=['Phone & charged power bank','Wallet & transport card','Water bottle','Today’s tickets & reservations'].map(name=>({id:uid(),name,done:false}));save()}return tr.dailyChecks[date]}
function checkView(){const checks=activeChecks(),daily=mode==='travel',done=checks.filter(c=>c.done).length;return `<div class="view-heading"><div><div class="eyebrow">READY, SET, GO</div><h1>${daily?(AppI18n.locale==='ko'?'오늘 챙길 준비물':'Your day bag'):'Your packing list'}</h1>${daily?`<p class="muted">${fmtDate(checklistDate())} · ${esc(currentCity())}</p>`:''}</div><span class="pill">${done} / ${checks.length} done</span></div>${daily?dateTabs():''}<div class="panel page-panel checklist"><h3>${daily?(AppI18n.locale==='ko'?'외출 전에 확인하세요. 날짜마다 따로 저장돼요.':'Before heading out. Each date has its own checklist.'):'A little preparation goes a long way.'}</h3><div class="progress"><i style="width:${checks.length?done/checks.length*100:0}%"></i></div>${checks.map(c=>`<label class="check-row ${c.done?'done':''}"><input type="checkbox" data-check="${c.id}" ${c.done?'checked':''}><span>${esc(c.name)}</span><button type="button" class="delete" aria-label="${esc(c.name)} Remove" data-action="delete-check" data-id="${c.id}">×</button></label>`).join('')}<form class="inline-form" id="check-form"><input aria-label="New packing item" name="name" placeholder="Anything else to pack?" required maxlength="80"><button class="btn primary">Add</button></form></div><p class="footnote">Saved automatically in this browser.</p>${ledgerView()}`}
function expenseCurrency(){return TravelPlanner.currency(cityInfo().country)||'USD'}
function tripStops(){return trip().days.flatMap((items,index)=>items.map(s=>({...s,day:index})))}
function ledgerView(){const all=tripStops(),expenses=trip().expenses||[],c=expenseCurrency();const planned=all.filter(s=>Number.isFinite(s.budgetAmount)),plannedTotals=planned.reduce((totals,s)=>{const code=stopBudget(s).currency||c;totals[code]=(totals[code]||0)+s.budgetAmount;return totals},{}),totals={};expenses.forEach(e=>totals[e.currency]=(totals[e.currency]||0)+e.amount);return `<section class="panel page-panel" style="margin-top:24px"><div class="section-title"><div><div class="eyebrow">${esc(trip().name)}</div><h2>Travel ledger</h2></div><button class="btn primary" data-action="add-expense">Add expense</button></div><div class="tool-grid"><div><h3>Planned budget</h3><strong class="big-number">${Object.entries(plannedTotals).map(([code,amount])=>money(amount,code)).join(' · ')||money(0,c)}</strong><p class="small-text">Only budgets you entered in itinerary stops are included. Unset budgets are not treated as free.</p></div><div><h3>Actual spending</h3><strong>${Object.entries(totals).map(([cur,amount])=>money(amount,cur)).join(' · ')||money(0,c)}</strong><p class="small-text">${AppI18n.translate('Remaining planned budget')}: ${[...new Set([...Object.keys(plannedTotals),...Object.keys(totals)])].map(code=>money((plannedTotals[code]||0)-(totals[code]||0),code)).join(' · ')||money(0,c)}</p><p class="small-text">Currencies are tracked separately; no automatic conversion.</p></div></div><details><summary>Itinerary budgets</summary>${all.map(s=>`<div class="result"><div>${AppI18n.translate('Day '+(s.day+1))} · ${esc(place(s.place)?.name)}<small>${Number.isFinite(s.budgetAmount)?money(s.budgetAmount,stopBudget(s).currency||c):AppI18n.translate('Budget not set')}</small></div><button class="btn small" data-action="ledger-budget" data-id="${s.id}" data-index="${s.day}">Edit budget</button><button class="btn small" data-action="add-expense" data-id="${s.id}">Record expense</button></div>`).join('')||'<p>No itinerary stops yet.</p>'}</details><h3>Expense records</h3>${expenses.length?expenses.map(e=>{const linked=all.find(s=>s.id===e.stopId);return `<div class="result"><div><strong>${esc(e.title)}</strong><small>${esc(e.date)} · ${AppI18n.translate(e.category)}${linked?' · '+esc(place(linked.place)?.name):''}</small>${e.note?`<p data-no-i18n style="white-space:pre-wrap">${esc(e.note)}</p>`:''}</div><strong>${money(e.amount,e.currency)}</strong><button class="btn small" data-action="edit-expense" data-id="${e.id}">Edit</button></div>`}).join(''):'<p>No expenses recorded yet.</p>'}</section>`}
function expenseForm(id,stopId=''){const expense=(trip().expenses||[]).find(e=>e.id===id),stops=tripStops(),linked=stops.find(s=>s.id===(expense?.stopId||stopId)),c=expense?.currency||(linked?stopBudget(linked).currency:null)||expenseCurrency();openModal(`<h2>${expense?'Edit expense':'Add expense'}</h2><form id="expense-form" data-id="${esc(expense?.id||'')}" data-trip="${esc(trip().id)}"><div class="form-grid"><label class="full">Description<input name="title" required maxlength="120" value="${esc(expense?.title||(linked?place(linked.place)?.name:''))}"></label><label>Amount<input type="number" name="amount" min="0" max="1000000000000" step="0.01" required value="${expense?.amount??''}"></label><label>Currency<select name="currency">${[...new Set([c,'GBP','EUR','USD','KRW','JPY','CAD','AUD','THB','VND','CNY','SGD','CHF'])].map(code=>`<option value="${code}" ${code===c?'selected':''}>${code}</option>`).join('')}</select></label><label>Date<input type="date" name="date" required value="${esc(expense?.date||new Date().toLocaleDateString('en-CA'))}"></label><label>Category<select name="category">${['Food & drinks','Transport','Tickets','Accommodation','Shopping','Other'].map(name=>`<option value="${name}" ${expense?.category===name?'selected':''}>${name}</option>`).join('')}</select></label><label class="full">Linked itinerary stop<select name="stopId"><option value="">No linked stop</option>${stops.map(s=>`<option value="${s.id}" ${s.id===(expense?.stopId||stopId)?'selected':''}>${AppI18n.translate('Day '+(s.day+1))} · ${esc(place(s.place)?.name)}</option>`).join('')}</select></label><label class="full">Notes<textarea name="note" rows="3" maxlength="5000">${esc(expense?.note||'')}</textarea></label></div><div class="dialog-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">Save</button></div></form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='add-expense')expenseForm(null,b.dataset.id);if(b.dataset.action==='edit-expense')expenseForm(b.dataset.id);if(b.dataset.action==='ledger-budget'){day=Number(b.dataset.index);editStop(b.dataset.id)}});
document.addEventListener('submit',e=>{if(e.target.id!=='expense-form')return;e.preventDefault();const f=e.target;if(f.dataset.trip!==trip().id)return;const values=Object.fromEntries(new FormData(f)),amount=Number(values.amount);if(!values.title.trim()||!Number.isFinite(amount)||amount<0||amount>1e12||!/^\d{4}-\d{2}-\d{2}$/.test(values.date)||!/^([A-Z]{3})$/.test(values.currency))return;const records=trip().expenses||(trip().expenses=[]),old=records.find(x=>x.id===f.dataset.id);const value={id:old?.id||uid(),title:values.title.trim(),amount,currency:values.currency,date:values.date,category:values.category,stopId:tripStops().some(s=>s.id===values.stopId)?values.stopId:'',note:values.note};if(old)Object.assign(old,value);else records.push(value);save();$('#modal').close();render()});
let storyChapter=-1;
function storyFor(id){const base=window.PLACE_STORIES[id];if(!base)return null;return AppI18n.locale==='ko'&&window.PLACE_STORIES_KO[id]?{...base,...window.PLACE_STORIES_KO[id]}:base}
function activeGuidePlace(){const s=stops().find(s=>s.id===selected)||stops()[0];return guideOverride||nearby||s&&place(s.place)||places.find(p=>window.PLACE_STORIES[p.id]&&haversine(p,cityInfo().center)<50000)||places.find(p=>window.PLACE_STORIES[p.id])}
function guideView(){const p=activeGuidePlace();if(!p)return '<div class="panel page-panel"><h1>Stories for your next adventure</h1><p>We do not have a researched story for this destination yet.</p><button class="btn" data-action="nav" data-value="plan">Back to itinerary</button></div>';const story=storyFor(p.id),chapters=story?.chapters||[],words=chapters.reduce((n,c)=>n+c.text.split(/\s+/).length,0);return `<div class="view-heading"><div><div class="eyebrow">YOUR POCKET TOUR GUIDE</div><h1>There is more to this place.</h1><p class="muted small-text">History, hidden details, and the stories that bring a place to life.</p></div><button class="btn" data-action="locate">${icon('pin')} ${watch!==null?'Location enabled':'Find nearby stories'}</button></div><div class="guide-layout"><article class="panel page-panel story-panel"><div class="eyebrow">${esc(p.name)}</div><h2>${esc(story?.title||AppI18n.translate('A story still to be told'))}</h2>${story?`<p class="muted small-text">${esc(story.theme)} · About ${Math.max(1,Math.ceil(words/135))} min · ${AppI18n.locale==='ko'?'한국어':'English'}</p><div class="story-player"><button class="btn primary" data-action="audio">${icon('headphones')} Play full story</button><button class="btn" data-action="pause-audio">Pause / resume</button><button class="btn" data-action="stop-audio">Stop</button><div id="audio-status" class="small-text muted" role="status">Ready when you are. Take a moment and look around.</div></div><div id="guide-text">${chapters.map((c,i)=>`<section class="story-chapter"><div class="section-title"><h3>${esc(c.title)}</h3><button class="btn small" data-action="chapter-audio" data-index="${i}" aria-label="Listen to ${esc(c.title)}">▷ Listen</button></div><p class="guide-text">${esc(c.text)}</p></section>`).join('')}</div><details class="story-sources"><summary>Historical sources</summary>${story.sources.map(src=>`<p><a href="${esc(src.url)}" target="_blank" rel="noopener">${esc(src.title)} ↗</a></p>`).join('')}<p>Original narration based on these sources. Scenes introduced with “imagine” are invitations to picture the past, not eyewitness accounts.</p></details>`:`<p>A researched historical story for this place is not available yet. We will not invent local history. Choose one of the available stories below.</p>`}<p class="footnote">Narrated in your selected language using your device’s voice. Nearby detection works while this page is open.</p></article><aside class="panel page-panel"><h3>Stories near your trip</h3>${places.filter(p=>window.PLACE_STORIES[p.id]&&haversine(p,cityInfo().center)<50000).map(p=>`<div class="result"><div>${esc(p.name)}<small>${esc(storyFor(p.id).theme)}</small></div><button class="btn small" data-action="guide-place" data-id="${p.id}">Explore</button></div>`).join('')||'<p class="muted">More local stories are being prepared.</p>'}<details class="story-library" style="margin-top:20px"><summary>${AppI18n.locale==='ko'?'전체 장소 이야기':'All place stories'} (${Object.keys(window.PLACE_STORIES).length})</summary>${places.filter(p=>window.PLACE_STORIES[p.id]).map(p=>`<div class="result"><div>${esc(p.name)}<small>${storyFor(p.id).chapters.length} ${AppI18n.locale==='ko'?'챕터':'chapters'}</small></div><button class="btn small" data-action="guide-place" data-id="${p.id}">Explore</button></div>`).join('')}</details><div class="next-location" style="margin-top:22px">${nearby?'Nearby: '+esc(nearby.name):'Enable location to discover stories within 300 m. You choose when to start listening.'}</div></aside></div>${watch!==null?'<button class="btn" style="margin-top:16px" data-action="stop-location">Disable location</button>':''}`}
let narrationRun=0;
function stopNarration(){narrationRun++;window.speechSynthesis?.cancel();if($('#audio-status'))$('#audio-status').textContent='Stopped. Start again whenever you like.'}
function narrateStory(index=-1){const p=activeGuidePlace(),story=storyFor(p?.id);if(!story)return;if(!('speechSynthesis' in window)){toast('This browser does not support narration. You can read the full story below.');return}stopNarration();const run=narrationRun,chapters=index<0?story.chapters:[story.chapters[index]],chunks=chapters.flatMap(c=>[{text:c.title.replace(/^\d+ · /,''),title:c.title},...c.text.match(/[^.!?]+[.!?]+|[^.!?]+$/g).map(text=>({text,title:c.title}))]);let at=0;function next(){if(run!==narrationRun)return;if(at>=chunks.length){if($('#audio-status'))$('#audio-status').textContent='Story complete. Look around with fresh eyes.';return}const chunk=chunks[at++],u=new SpeechSynthesisUtterance(chunk.text);u.lang=AppI18n.locale==='ko'?'ko-KR':'en-US';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang===u.lang)||speechSynthesis.getVoices().find(v=>v.lang.startsWith(AppI18n.locale));if(voice)u.voice=voice;u.onstart=()=>{if($('#audio-status'))$('#audio-status').textContent='Now playing · '+chunk.title};u.onend=next;u.onerror=e=>{if(run===narrationRun&&e.error!=='interrupted'&&e.error!=='canceled')toast('Narration is unavailable. The complete story is ready to read.')};speechSynthesis.speak(u)}next()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='chapter-audio')narrateStory(Number(b.dataset.index));if(b.dataset.action==='pause-audio'&&window.speechSynthesis){if(speechSynthesis.paused){speechSynthesis.resume();if($('#audio-status'))$('#audio-status').textContent='Narration resumed.'}else if(speechSynthesis.speaking){speechSynthesis.pause();if($('#audio-status'))$('#audio-status').textContent='Paused. Take your time.'}}});
function toolsView(){return TravelTools.render({destination:cityInfo(),city:currentCity()})}
function updateClock(){const n=new Date();$('#paris-time').textContent=n.toLocaleTimeString(AppI18n.locale==='ko'?'ko-KR':'en-US',{timeZone:cityInfo().tz,hour:'2-digit',minute:'2-digit'});$('#seoul-time').textContent='Seoul '+n.toLocaleTimeString(AppI18n.locale==='ko'?'ko-KR':'en-US',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit'})}
const routeCache=new Map();
const routeKey=()=>trip().id+':'+cityInfo().center.lat+','+cityInfo().center.lng;
const routeThemes=[{name:'City highlights',desc:'Main sights and nearby stops for a first visit.',types:null,start:9,end:19},{name:'Art & culture',desc:'Museums, galleries and historic places, with time to pause.',types:['Museum','Gallery','Castle'],start:10,end:18},{name:'A relaxed afternoon',desc:'A shorter walk with outdoor sights and a café break.',types:['Walk','Viewpoint','Sight','Monument'],start:13,end:18}];
function coursesView(){const cached=routeCache.get(routeKey());if(!cached){routeCache.set(routeKey(),{loading:true});queueMicrotask(()=>loadRoutes());}const state=routeCache.get(routeKey());return `<div class="view-heading"><div><div class="eyebrow">DISCOVER YOUR DESTINATION</div><h1>${esc(currentCity())} · ${AppI18n.translate('Recommended routes')}</h1><p class="muted">Routes built from nearby places. Review the stops, then make the day yours.</p></div><button class="btn" data-action="refresh-routes" ${state.loading?'disabled':''}>Refresh routes</button></div>${dateTabs()}<p class="footnote">Visit times are estimates. Check opening hours and tickets before you go.</p>${state.loading?'<div class="panel page-panel" role="status">Finding routes near your destination…</div>':state.error?'<div class="panel page-panel"><p>'+esc(state.error)+'</p><button class="btn" data-action="refresh-routes">Try again</button></div>':`<div class="tool-grid">${state.routes.map((r,i)=>`<article class="panel page-panel"><h2>${AppI18n.translate(r.name)}</h2><p>${AppI18n.translate(r.desc)}</p><p class="small-text">${r.start}:00 – ${r.end}:00</p>${r.items.map(item=>`<p class="small-text">${esc(item.time)} · ${esc(item.place.name)}<br><span class="muted">${item.duration} ${AppI18n.translate('min stay')}</span></p>`).join('')}<button class="btn primary" data-action="preview-route" data-index="${i}">Preview this route</button></article>`).join('')}</div>${state.partial?'<p class="footnote">Live search is unavailable. These routes use places already available for this destination.</p>':''}`}`}
async function loadRoutes(){const id=trip().id,key=routeKey(),info=cityInfo();let partial=false;let candidates=[...TravelPlanner.highlights,...places,...data.customPlaces].filter(p=>!p.pendingMeal&&p.type!=='Stay'&&haversine(p,info.center)<15000);try{const found=await TravelPlanner.discover(info.center,info.country);const byName=new Map(candidates.map(p=>[p.name.toLowerCase(),p]));found.forEach(p=>{const old=byName.get(p.name.toLowerCase());if(!old||old.source==='OpenStreetMap')byName.set(p.name.toLowerCase(),p)});candidates=[...byName.values()]}catch{partial=true}const routes=[];for(const theme of routeThemes){const pool=candidates.map(p=>TravelPlanner.details(p,info.country)).filter(p=>!theme.types||theme.types.includes(p.type)||['Restaurant','Café'].includes(p.type));if(!pool.some(p=>!['Restaurant','Café'].includes(p.type)))continue;const planned=TravelPlanner.plan({places:pool,center:info.center,country:info.country,days:1,startHour:theme.start,endHour:theme.end})[0];if(planned.items.some(i=>i.label==='Sightseeing'))routes.push({...theme,...planned})}routeCache.set(key,routes.length?{routes,partial}:{error:partial?'Could not load nearby places. Please try again.':'Not enough nearby places were found to build a route.'});if(trip().id===id&&view==='courses')render()}
async function previewRoute(index){const cached=routeCache.get(routeKey()),route=cached?.routes?.[index];if(!route)return;const id=trip().id,targetDay=day,items=route.items.map(i=>({...i,place:{...i.place}}));openModal('<h2>'+AppI18n.translate(route.name)+'</h2><p>Finding restaurants and cafés along your route…</p>');const dialog=$('#modal');await TravelPlanner.addDining([{items,missing:[...route.missing]}],cityInfo().country);if(!dialog.open||trip().id!==id)return;generatedPlan={tripId:id,replace:true,days:[{day:targetDay,items}],source:'Recommended route'};openModal('<h2>'+AppI18n.translate(route.name)+'</h2><p>'+AppI18n.translate(stops().length?'Applying this route replaces the selected day. Other days stay unchanged.':'This route will be added to the selected day.')+'</p>'+items.map(i=>'<p>'+esc(i.time)+' · '+esc(i.place.name)+'<br><span class="muted">'+i.duration+' '+AppI18n.translate('min stay')+' · '+esc(budgetText(TravelPlanner.budget(i.place,cityInfo().country)))+'</span></p>').join('')+'<div class="dialog-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="apply-plan">Use this plan</button></div>')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='refresh-routes'){routeCache.delete(routeKey());render()}if(b.dataset.action==='preview-route')previewRoute(Number(b.dataset.index))});

function openModal(html){$('#modal').innerHTML=`<div class="dialog-top"><span></span><button data-action="close" aria-label="Close">×</button></div>${html}`;$('#modal').showModal()}
const popularDestinations=[
['Paris','FR',48.8566,2.3522,'Europe/Paris','France'],['Seoul','KR',37.5665,126.978,'Asia/Seoul','South Korea'],['Tokyo','JP',35.6762,139.6503,'Asia/Tokyo','Japan'],['London','GB',51.5074,-.1278,'Europe/London','United Kingdom'],['New York','US',40.7128,-74.006,'America/New_York','United States'],['Rome','IT',41.9028,12.4964,'Europe/Rome','Italy'],['Bangkok','TH',13.7563,100.5018,'Asia/Bangkok','Thailand'],['Sydney','AU',-33.8688,151.2093,'Australia/Sydney','Australia']].map(([name,country,lat,lng,tz,countryName])=>({name,country,center:{lat,lng},tz,en:countryName.toUpperCase()+', '+name.toUpperCase(),flag:flagFor(country),countryName}));
function flagFor(code){return /^[A-Z]{2}$/.test(code)?String.fromCodePoint(...[...code].map(c=>127397+c.charCodeAt(0))):'🌎'}
let pickedDestination=null,cityResults=[],citySearchVersion=0;
document.addEventListener('change',e=>{if(e.target.id!=='app-language')return;stopNarration();AppI18n.set(e.target.value);render();toast('Interface language updated.')});
function completedHome(){return `<section class="panel page-panel"><h1>Ready for your next adventure?</h1><p>Your completed trips and notes are safely kept on this device.</p><button class="btn primary" data-action="new-trip">New trip</button> <button class="btn" data-action="completed-trips">Completed trips</button></section>`}
function completedTrips(){openModal('<h2>Completed trips</h2><p>Open a trip to revisit its itinerary and notes, or restore it to your current trips.</p>'+data.trips.map((t,i)=>t.completed?'<div class="result"><div>'+esc(t.name)+'<small>'+esc(t.start)+' — '+esc(t.end)+'</small></div><button class="btn small" data-action="view-completed" data-index="'+i+'">View trip</button><button class="btn small" data-action="restore-trip" data-index="'+i+'">Restore trip</button></div>':'').join('')+(data.trips.some(t=>t.completed)?'':'<p>No completed trips yet.</p>'))}
function viewCompleted(index){const t=data.trips[index];if(!t?.completed)return;openModal('<h2>'+esc(t.name)+'</h2>'+t.days.map((items,i)=>'<h3>'+AppI18n.translate('Day '+(i+1))+'</h3>'+items.map(s=>'<div class="result" style="display:block"><strong>'+esc(s.time)+' · '+esc(place(s.place)?.name||'')+'</strong>'+(s.reservation?'<p>'+AppI18n.translate('Reservation')+' '+esc(s.reservation)+'</p>':'')+(s.notes?'<p data-no-i18n style="white-space:pre-wrap">'+esc(s.notes)+'</p>':'')+'</div>').join('')).join('')+'<div class="dialog-actions"><button class="btn" data-action="completed-trips">Back</button><button class="btn primary" data-action="restore-trip" data-index="'+index+'">Restore trip</button></div>')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,index=Number(b.dataset.index);if(a==='completed-trips')completedTrips();if(a==='view-completed')viewCompleted(index);if(a==='complete-trip'){stopNarration();if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null}trip().completed=true;trip().completedAt=new Date().toISOString();const next=data.trips.findIndex(t=>!t.completed);if(next>=0)data.active=next;day=0;selected=null;guideOverride=null;nearby=null;view='plan';save();$('#modal').close();render();toast('Trip moved to Completed trips. Your itinerary and notes are kept.')}if(a==='restore-trip'){const t=data.trips[index];if(!t?.completed)return;delete t.completed;delete t.completedAt;data.active=index;day=0;selected=null;view='plan';guideOverride=null;save();$('#modal').close();render();toast('Trip restored.')}});
function tripForm(edit=false){const t=trip();pickedDestination=edit?{...cityInfo(),name:t.city}:null;openModal(`<h2>${edit?'Edit your trip':'Where to next?'}</h2><p>A big city, a quiet town, somewhere new. Search worldwide.</p><form id="trip-form" data-edit="${edit}"><div class="form-grid">${edit?`<div class="full"><label>Destinations</label><div class="trip-destinations">${t.days.map((_,i)=>`<div class="small-text">${AppI18n.translate('Day '+(i+1))} · ${esc(destinationFor(i).flag||'')} ${esc(destinationFor(i).name||t.city)}</div>`).join('')}</div><button type="button" class="btn" style="margin-top:12px" data-action="add-trip-destination">＋ Add destination</button><div id="trip-destination-editor"></div></div>`:`<label class="full">Destination<div class="inline-form" style="margin:0"><input id="city-search" placeholder="Search any city, e.g. Barcelona" autocomplete="off"><button type="button" class="btn" data-action="search-city">Search</button></div></label><div class="full" id="city-results">${popularDestinations.map((d,i)=>`<button type="button" class="pref" style="margin:3px" data-action="popular-city" data-index="${i}">${d.flag} ${d.name}</button>`).join('')}</div><div class="full next-location" id="selected-destination">Choose a destination to continue.</div>`}<label class="full">Trip name<input name="name" value="${edit?esc(t.name):''}" placeholder="My next adventure" required maxlength="60"></label><label>Start date<input type="date" name="start" value="${edit?t.start:'2026-10-12'}" required></label><label>End date<input type="date" name="end" value="${edit?t.end:'2026-10-16'}" required></label></div><p id="form-error" role="alert"></p><p class="footnote">City search: Open-Meteo / GeoNames. Maps: NAVER in South Korea, Google elsewhere after API setup.</p><div class="dialog-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary">${edit?'Save changes':'Create trip'}</button>${edit&&!t.completed?'<button type="button" class="btn" data-action="complete-trip">Complete trip</button>':''}</div></form>`)}
function addTripDestination(){pickedDestination=null;$('#trip-destination-editor').innerHTML=`<div class="next-location" style="margin-top:12px"><p>Choose a city and day range, then save your trip changes.</p><div class="inline-form"><input id="city-search" aria-label="Destination search" placeholder="Search any city, e.g. Barcelona"><button type="button" class="btn" data-action="search-city">Search</button></div><div id="city-results"></div><p id="selected-destination">Choose a destination to continue.</p><div class="form-grid"><label>From day<select id="destination-from">${trip().days.map((_,i)=>`<option value="${i}" ${i===day?'selected':''}>${AppI18n.translate('Day '+(i+1))}</option>`).join('')}</select></label><label>Through day<select id="destination-to">${trip().days.map((_,i)=>`<option value="${i}" ${i===day?'selected':''}>${AppI18n.translate('Day '+(i+1))}</option>`).join('')}</select></label></div></div>`}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="add-trip-destination"]'))addTripDestination()});
function dayDestinationForm(){pickedDestination=null;openModal(`<h2>Set destinations by day</h2><p>Choose a city and the days you will stay there. Existing stops and expenses are kept.</p><div class="inline-form"><input id="city-search" placeholder="Search any city, e.g. Barcelona"><button class="btn" data-action="search-city">Search</button></div><div id="city-results"></div><p id="selected-destination">Choose a destination to continue.</p><div class="form-grid"><label>From day<select id="destination-from">${trip().days.map((_,i)=>`<option value="${i}" ${i===day?'selected':''}>${AppI18n.translate('Day '+(i+1))}</option>`).join('')}</select></label><label>Through day<select id="destination-to">${trip().days.map((_,i)=>`<option value="${i}" ${i===day?'selected':''}>${AppI18n.translate('Day '+(i+1))}</option>`).join('')}</select></label></div><p id="form-error" role="alert"></p><div class="dialog-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="save-day-destination">Save</button></div>`)}
function assignDestination(from,to,destination){if(!destination||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<from||to>=trip().days.length)return false;for(let i=from;i<=to;i++){const oldCurrency=TravelPlanner.currency(destinationFor(i).country);trip().days[i].forEach(s=>{if(Number.isFinite(s.budgetAmount)&&!s.budgetCurrency)s.budgetCurrency=oldCurrency})}trip().dayDestinations||={};for(let i=from;i<=to;i++)trip().dayDestinations[i]={...destination};return true}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='day-destination')dayDestinationForm();if(b.dataset.action==='save-day-destination'){const from=Number($('#destination-from').value),to=Number($('#destination-to').value);if(!assignDestination(from,to,pickedDestination)){$('#form-error').textContent='Choose a destination and a valid day range.';return}day=from;selected=null;guideOverride=null;nearby=null;save();$('#modal').close();render()}});
function chooseDestination(destination){pickedDestination=destination;$('#selected-destination').textContent=`${destination.flag} ${destination.name}, ${destination.countryName||destination.country} · ${destination.country==='KR'?'NAVER Maps':'Google Maps'}`;const name=$('#trip-form input[name="name"]');if(name&&!name.value)name.value=destination.name+', at my own pace';$('#form-error').textContent=''}
async function searchCities(){const q=$('#city-search').value.trim(),target=$('#city-results'),version=++citySearchVersion;if(TravelCitySearch.normalize(q).name.length<2){target.textContent='Enter at least two characters.';return}target.textContent='Searching destinations…';try{const body={results:await TravelCitySearch.search(q)};if(version!==citySearchVersion||!target.isConnected)return;cityResults=(body.results||[]).filter(r=>r.country_code&&Number.isFinite(r.latitude)&&Number.isFinite(r.longitude)).map(r=>({name:r.name,country:r.country_code,countryName:r.country||r.country_code,region:r.admin1||'',center:{lat:r.latitude,lng:r.longitude},tz:r.timezone||'UTC',en:(r.country||r.country_code).toUpperCase()+', '+r.name.toUpperCase(),flag:flagFor(r.country_code)}));target.innerHTML=cityResults.length?cityResults.map((r,i)=>`<button type="button" class="result" style="width:100%;text-align:left;margin:7px 0" data-action="choose-city" data-index="${i}"><span>${r.flag} ${esc(r.name)}<small>${esc(r.region)}, ${esc(r.countryName)}</small></span><span>＋</span></button>`).join(''):'No matching cities. Try a nearby town or a different spelling.'}catch{if(version===citySearchVersion&&target.isConnected)target.textContent='City search is unavailable. Check your connection and try again. You can still choose a suggested destination.'}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='search-city')searchCities();if(b.dataset.action==='popular-city')chooseDestination(popularDestinations[Number(b.dataset.index)]);if(b.dataset.action==='choose-city')chooseDestination(cityResults[Number(b.dataset.index)])});
document.addEventListener('keydown',e=>{if(e.target.id==='city-search'&&e.key==='Enter'){e.preventDefault();searchCities()}});
let generatedPlan=null,plannerBusy=false;
function autoPlan(){generatedPlan=null;openModal(`<h2>A good day, automatically.</h2><p>Discover ${esc(currentCity())} with nearby sights grouped into a practical visit order. Every stop stays editable.</p><label class="utility-label">Plan for<select id="plan-scope"><option value="empty">Empty days only</option><option value="current">Replace this day after preview</option></select></label><div class="form-grid plan-time-grid"><label>Start your day<input id="plan-start" type="time" value="09:00"></label><label>End your day<input id="plan-end" type="time" min="06:01" max="23:00" value="21:00"></label></div><div class="next-location"><p>Automatic planning fills empty days for the selected destination only. Other destinations and existing plans are kept unless you choose to replace this day.</p><p>Nearby restaurants are added for lunch and dinner, with an afternoon café break. There is no daily stop limit.</p><p>Suggestions are based on distance, not ratings. Opening hours and bookings need checking. If nearby options are missing, the preview will tell you.</p></div><div id="plan-preview" aria-live="polite"></div><div class="dialog-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" id="generate-plan" data-action="generate-plan">Generate preview</button></div>`)}
async function generatePlan(button){if(plannerBusy)return;const replace=$('#plan-scope').value==='current';const empty=replace?[day]:trip().days.map((items,i)=>items.length||haversine(destinationFor(i).center,cityInfo().center)>1000?null:i).filter(i=>i!==null);if(!empty.length){$('#plan-preview').innerHTML='<p>Every day already has plans. Add a new trip or extend your trip dates to create an empty day. Your existing stops have been kept.</p>';return}const start=$('#plan-start').value;if(!start){toast('Choose a start time.');return}const [h,m]=start.split(':').map(Number);if(h<6||h>14){toast('Choose a start time between 06:00 and 14:59.');return}const finish=$('#plan-end').value;if(!finish){toast('Choose a finish time after your start time, no later than 23:00.');return}const [eh,em]=finish.split(':').map(Number),endHour=eh+em/60;if(endHour<=h+m/60||endHour>23){toast('Choose a finish time after your start time, no later than 23:00.');return}plannerBusy=true;button.disabled=true;const target=$('#plan-preview'),tripId=trip().id,pace=1;target.innerHTML='<p>Finding places and grouping nearby stops…</p>';try{const existing=new Set(trip().days.filter((_,i)=>!replace||i!==day).flat().map(s=>s.place));let candidates=[...TravelPlanner.highlights,...places,...data.customPlaces].filter(p=>p.type!=='Stay'&&haversine(p,cityInfo().center)<15000&&!existing.has(p.id));let source='Curated place collection';{try{const found=await TravelPlanner.discover(cityInfo().center,cityInfo().country);const names=new Set(candidates.map(p=>p.name.toLowerCase()));found.forEach(p=>{const prior=candidates.find(q=>q.id===p.id||q.name.toLowerCase()===p.name.toLowerCase());if(prior&&prior.source==='OpenStreetMap')Object.assign(prior,p);if(!existing.has(p.id)&&!names.has(p.name.toLowerCase())&&!candidates.some(q=>q.type===p.type&&haversine(p,q)<20)){candidates.push(p);names.add(p.name.toLowerCase())}});source='Curated places + OpenStreetMap'}catch(error){if(!candidates.length)throw error;source='Curated places · live discovery unavailable'}}if(!target.isConnected||trip().id!==tripId)return;if(!candidates.length)throw Error('No suitable places found. Add a few custom places or try a nearby destination.');const result=TravelPlanner.plan({places:candidates,center:cityInfo().center,days:empty.length,pace,startHour:h+m/60,endHour,country:cityInfo().country});target.innerHTML='<p>Finding restaurants and cafés along your route…</p>';await TravelPlanner.addDining(result,cityInfo().country);if(!target.isConnected||trip().id!==tripId)return;generatedPlan={tripId,replace,days:result.map((d,i)=>({...d,day:empty[i]})),source};target.innerHTML=`<p class="small-text muted">${esc(source)} · Distances start at the city center.<br>Travel times are rough walking allowances, not live routing. Only sourced admission prices are shown. Other prices need checking. Visit durations are editable estimates unless a source is linked. Suggested booking times are not confirmed reservations.</p>${generatedPlan.days.filter(d=>d.items.length).map(d=>`<div class="result" style="display:block;margin:10px 0"><strong>Day ${d.day+1}</strong><small>${(d.distance/1000).toFixed(1)} km straight-line sequence</small><p class="small-text">${d.items.map(i=>esc(i.time)+' · '+AppI18n.translate(i.label||'Sightseeing')+' · '+esc(i.place.name)+' · '+i.duration+' '+AppI18n.translate('min stay')+' · '+esc(budgetText(TravelPlanner.budget(i.place,cityInfo().country)))+(i.place.bookingSuggested?' · <a href="'+esc(bookingLink(i.place))+'" target="_blank" rel="noopener">'+AppI18n.translate('Suggested booking')+' '+esc(i.time)+' ↗</a>':'')+(i.place.searchUrl?' <a href="'+esc(i.place.searchUrl)+'" target="_blank" rel="noopener">'+AppI18n.translate('Browse nearby options')+' ↗</a>':'')).join('<br>')}</p>${d.missing?.length?'<p>'+AppI18n.translate('No nearby option found: ')+d.missing.map(label=>AppI18n.translate(label)).join(', ')+'</p>':''}</div>`).join('')}<p class="small-text">${generatedPlan.days.filter(d=>!d.items.length).length?'Some days are left free because not enough distinct places were found.':''}</p><button class="btn primary" data-action="apply-plan">Use this plan</button>`}catch(error){if(target.isConnected)target.textContent=error.message}finally{plannerBusy=false;button.disabled=false}}
function applyPlan(){if(!generatedPlan||generatedPlan.tripId!==trip().id)return;let count=0;generatedPlan.days.forEach(d=>{if(trip().days[d.day].length&&!generatedPlan.replace)return;if(!d.items.length)return;if(generatedPlan.replace)trip().days[d.day]=[];d.items.forEach(i=>{if(i.place.pendingMeal)i.place.id=uid();if(!place(i.place.id))data.customPlaces.push(i.place);else Object.assign(place(i.place.id),i.place);trip().days[d.day].push({...item(i.place.id,i.time),duration:i.duration,label:i.label});count++})});if(!count){toast('No empty days were changed.');return}day=generatedPlan.days.find(d=>d.items.length)?.day||0;save();$('#modal').close();view='plan';mode='planning';render();toast(count+' stops added. Move, edit or remove any of them.');generatedPlan=null}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='auto-plan')autoPlan();if(b.dataset.action==='generate-plan')generatePlan(b);if(b.dataset.action==='apply-plan')applyPlan()});
function addPlace(){openModal(`<h2>Where would you like to go?</h2><p>DAY ${day+1} · ${esc(currentCity())} Search our place collection or add your own.</p><input id="place-search" placeholder="Louvre, gardens, cafés…" aria-label="Search places" style="width:100%"><div class="results" id="place-results"></div><button class="add-stop" data-action="custom-place">＋ Add a custom place</button>`);searchPlaces('')}
function searchPlaces(q){$('#place-results').innerHTML=[...places,...data.customPlaces].filter(p=>haversine(p,cityInfo().center)<50000).filter(p=>(p.name+p.en+p.type).toLowerCase().includes(q.toLowerCase())).map(p=>`<div class="result"><div>${esc(p.name)}<small>${esc(p.en)} · ${esc(p.type)}</small></div><button class="btn small" data-action="choose-place" data-id="${p.id}">Add</button></div>`).join('')||'<p>No places found. Try adding your own.</p>'}
function editStop(id){const s=stops().find(s=>s.id===id);openModal(`<h2>${esc(place(s.place).name)}</h2><form id="stop-form" data-id="${id}"><div class="form-grid"><label>Visit time<input type="time" name="time" required value="${esc(s.time)}"></label><label>Reservation time<input type="time" name="reservation" value="${esc(s.reservation)}"></label><label>Stay duration (minutes)<input type="number" name="duration" min="5" max="720" step="5" required value="${s.duration||place(s.place).duration}"></label><label>My budget (${esc(s.budgetCurrency||TravelPlanner.currency(cityInfo().country)||'local currency')})<input name="budgetAmount" type="number" min="0" step="0.01" value="${s.budgetAmount??''}" placeholder="Optional"></label><label class="full">Notes<textarea name="notes" rows="4" maxlength="5000" placeholder="Reservation details, things to remember, or anything for this stop…">${esc(s.notes||'')}</textarea></label></div><div class="dialog-actions"><button type="button" class="btn" data-action="remove-stop" data-id="${id}">Remove stop</button><button class="btn primary">Save</button></div></form>`)}
function locate(){if(!navigator.geolocation){toast('This browser does not support location.');return}if(watch!==null){toast('Location is already enabled.');return}toast('Allow location access to find nearby places.');watch=navigator.geolocation.watchPosition(p=>{position={lat:p.coords.latitude,lng:p.coords.longitude};const n=[...places,...data.customPlaces].filter(p=>p.type!=='Stay').find(p=>haversine(position,p)<300);const changed=nearby?.id!==n?.id;nearby=n||null;if(changed&&n)toast(n.name+' is nearby. Open its story.');if(view==='plan'||view==='guide')render()},()=>{watch=null;toast('Location is unavailable. Check browser permissions and GPS.');if(view==='guide')render()},{enableHighAccuracy:true,maximumAge:30000,timeout:15000})}
function speak(text,lang='en-US'){if(!('speechSynthesis'in window)){toast('This browser does not support speech.');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=lang;utterance.rate=.93;utterance.onerror=()=>toast('Audio could not play. Check your device’s speech settings.');speechSynthesis.speak(utterance)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,v=b.dataset.value,i=Number(b.dataset.index);if(a==='nav'){stopNarration();view=v;guideOverride=null;render()}else if(a==='mode'){stopNarration();mode=v;view='plan';render()}else if(a==='day'){day=i;render()}else if(a==='table'){table=!table;render()}else if(a==='new-trip')tripForm();else if(a==='edit-trip')tripForm(true);else if(a==='trip-list'){openModal('<h2>Your trips</h2><div class="results">'+data.trips.map((t,j)=>t.completed?'':'<button class="result" data-action="switch-trip" data-index="'+j+'"><span>'+esc(t.name)+'<small>'+esc(t.city)+'</small></span><span>→</span></button>').join('')+'</div>')}else if(a==='switch-trip'){$('#modal').close();data.active=i;day=0;guideOverride=null;nearby=null;save();render()}else if(a==='close')$('#modal').close();else if(a==='add-place')addPlace();else if(a==='choose-place'){const s=item(id,'10:00');stops().push(s);selected=s.id;save();$('#modal').close();render();toast('Place added. Adjust the time to suit your day.')}else if(a==='select'){selected=id;render()}else if(a==='move'){const j=i+Number(b.dataset.delta);if(j>=0&&j<stops().length){[stops()[i],stops()[j]]=[stops()[j],stops()[i]];save();render()}}else if(a==='edit-stop')editStop(id);else if(a==='remove-stop'){trip().days[day]=stops().filter(s=>s.id!==id);save();$('#modal').close();render()}else if(a==='pref'){data.prefs[v]=!data.prefs[v];save();render()}else if(a==='delete-check'){const checks=activeChecks(),at=checks.findIndex(c=>c.id===id);if(at>=0)checks.splice(at,1);save();render()}else if(a==='guide-place'){stopNarration();guideOverride=place(id);render()}else if(a==='audio')narrateStory();else if(a==='stop-audio')stopNarration();else if(a==='phrase-audio')speak($('#translated').textContent,'fr-FR');else if(a==='locate')locate();else if(a==='stop-location'){navigator.geolocation.clearWatch(watch);watch=null;nearby=null;render()}else if(a==='complete'){const index=stops().findIndex(s=>s.id===selected);if(index<stops().length-1){selected=stops()[index+1].id;render()}else toast('That is your last stop today. Enjoy the moment!')}else if(a==='map-filter'){if(v==='all'){filter=v;render()}else{const q=currentCity()+' '+(v==='toilet'?'public restrooms':'drinking fountains');window.open((cityInfo().country==='KR'?'https://map.naver.com/p/search/':'https://www.google.com/maps/search/?api=1&query=')+encodeURIComponent(q),'_blank','noopener')}}else if(a==='weather')getWeather(b);else if(a==='export'){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='eodiro-trips.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(a==='custom-place'){openModal(`<h2>Add a custom place</h2><p>Enter the coordinates shown on your map.</p><form id="custom-form"><div class="form-grid"><label class="full">Place name<input name="name" required maxlength="80"></label><label>Latitude<input name="lat" type="number" step="any" min="-90" max="90" required placeholder="48.8606"></label><label>Longitude<input name="lng" type="number" step="any" min="-180" max="180" required placeholder="2.3376"></label><label>Type<select name="type"><option>Sight</option><option>Stay</option><option>Restaurant</option><option>Café</option></select></label><label>Budget (€)<input name="cost" type="number" min="0" max="100000" value="0" required></label></div><div class="dialog-actions"><button class="btn primary">Save & add to itinerary</button></div></form>`)}});
document.addEventListener('input',e=>{if(e.target.id==='city-search'){pickedDestination=null;if($('#selected-destination'))$('#selected-destination').textContent='Search and choose a destination.'}if(e.target.id==='place-search')searchPlaces(e.target.value);if(['eur','rate'].includes(e.target.id)){const euro=Number($('#eur').value),rate=Number($('#rate').value);$('#converted').textContent=Number.isFinite(euro)&&Number.isFinite(rate)&&euro>=0&&rate>0?'₩'+Math.round(euro*rate).toLocaleString():'Enter a valid amount and exchange rate.'}});
document.addEventListener('change',e=>{if(e.target.dataset.check){activeChecks().find(c=>c.id===e.target.dataset.check).done=e.target.checked;save();render()}if(e.target.id==='phrase')$('#translated').textContent=e.target.value});
document.addEventListener('submit',e=>{const f=e.target;if(!['trip-form','stop-form','check-form','custom-form'].includes(f.id))return;e.preventDefault();const values=Object.fromEntries(new FormData(f));if(f.id==='check-form'){if(!values.name.trim())return;activeChecks().push({id:uid(),name:values.name.trim(),done:false});save();render()}else if(f.id==='trip-form'){const count=Math.round((new Date(values.end+'T12:00:00Z')-new Date(values.start+'T12:00:00Z'))/86400000)+1;if(!Number.isFinite(count)||count<1||count>30){$('#form-error').textContent='Choose a trip duration between 1 and 30 days.';return}if(!values.name.trim()){$('#form-error').textContent='Please enter a trip name.';return}const edit=f.dataset.edit==='true';const hasDestinationEditor=edit&&!!$('#trip-destination-editor #destination-from');const destinationFrom=hasDestinationEditor?Number($('#destination-from').value):0,destinationTo=hasDestinationEditor?Number($('#destination-to').value):0;if(hasDestinationEditor&&(!pickedDestination||destinationFrom>destinationTo||destinationTo>=count)){$('#form-error').textContent='Choose a destination and a valid day range.';return}if(!edit&&!pickedDestination){$('#form-error').textContent='Search for and select a destination first.';return}if(edit&&count<trip().days.length&&trip().days.slice(count).some(d=>d.length)){$('#form-error').textContent='There are plans on the days you are removing. Move or remove those stops first.';return}if(edit){if(trip().dayDestinations)Object.keys(trip().dayDestinations).forEach(k=>{if(Number(k)>=count)delete trip().dayDestinations[k]});Object.assign(trip(),{name:values.name.trim(),start:values.start,end:values.end,days:Array.from({length:count},(_,i)=>trip().days[i]||[])})}else{data.trips.push({id:uid(),name:values.name.trim(),city:pickedDestination.name,destination:pickedDestination,start:values.start,end:values.end,days:Array.from({length:count},()=>[])});data.active=data.trips.length-1}if(hasDestinationEditor)assignDestination(destinationFrom,destinationTo,pickedDestination);day=0;save();$('#modal').close();view='plan';guideOverride=null;nearby=null;render()}else if(f.id==='stop-form'){const edited=stops().find(s=>s.id===f.dataset.id);if(!edited)return;const duration=Number(values.duration),amount=values.budgetAmount===''?null:Number(values.budgetAmount);if(!Number.isFinite(duration)||duration<5||duration>720||amount!==null&&(!Number.isFinite(amount)||amount<0))return;Object.assign(edited,values,{duration});if(amount===null)delete edited.budgetAmount;else{edited.budgetAmount=amount;edited.budgetCurrency=values.budgetCurrency||edited.budgetCurrency||expenseCurrency()}save();$('#modal').close();render()}else if(f.id==='custom-form'){if(!values.name.trim())return;const p={id:uid(),name:values.name.trim(),en:'Custom place',country:cityInfo().country,lat:Number(values.lat),lng:Number(values.lng),type:values.type,cost:Number(values.cost),duration:60,guide:'A place you added. A detailed guide is not available yet.'};if(!Number.isFinite(p.lat)||Math.abs(p.lat)>90||!Number.isFinite(p.lng)||Math.abs(p.lng)>180)return;data.customPlaces.push(p);const s=item(p.id,'10:00');stops().push(s);selected=s.id;save();$('#modal').close();render()}});
document.addEventListener('dragstart',e=>{const stop=e.target.closest('[data-stop]');if(stop){dragged=stop.dataset.stop;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move'}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-stop]'))e.preventDefault()});document.addEventListener('drop',e=>{const stop=e.target.closest('[data-stop]');if(!stop||!dragged)return;e.preventDefault();const from=stops().findIndex(s=>s.id===dragged),to=stops().findIndex(s=>s.id===stop.dataset.stop);if(from>=0&&to>=0&&from!==to){stops().splice(to,0,stops().splice(from,1)[0]);save();render()}dragged=null});
async function getWeather(button){button.disabled=true;const target=$('#weather-result');target.textContent='Checking the weather…';try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${cityInfo().center.lat}&longitude=${cityInfo().center.lng}&current=temperature_2m,precipitation&timezone=${encodeURIComponent(cityInfo().tz)}`,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const d=await r.json();target.textContent=`${currentCity()} ${d.current.temperature_2m}°C · Precipitation ${d.current.precipitation} mm · ${d.current.time.replace('T',' ')} (local) · Source: Open-Meteo`;}catch{target.textContent='Weather is unavailable. Check your connection and try again.'}finally{button.disabled=false}}
function travelDashboard(){const current=stops().find(s=>s.id===selected)||stops()[0],index=stops().findIndex(s=>s.id===selected);return `<div class="travel-topline"><div><div class="eyebrow">OUT HERE, RIGHT NOW</div><h1>Your day, one moment at a time.</h1><p class="muted">${esc(currentCity())} · ${fmtDate(new Date(Date.parse(trip().start+'T12:00:00Z')+day*86400000).toISOString().slice(0,10))} · Day ${day+1} of ${trip().days.length}</p></div><button class="btn primary" data-action="locate">${icon('pin')} ${position?'Update location':'Enable location'}</button></div><div class="travel-status"><span>${icon('compass')} ON YOUR TRIP</span><span>${stops().length?index+1:0} / ${stops().length} stops</span><span>${position?'Location connected':'Location off'}</span></div>${travelView()}<div class="travel-quick"><button class="panel" data-action="nav" data-value="guide">${icon('headphones')}<strong>Listen & explore</strong><span>Stories around you →</span></button><button class="panel" data-action="map-filter" data-value="toilet">${icon('pin')}<strong>Find a restroom</strong><span>Open nearby search →</span></button><button class="panel" data-action="nav" data-value="tools">${icon('tools')}<strong>Travel essentials</strong><span>Weather, time & phrases →</span></button><button class="panel" data-action="nav" data-value="checklist">${icon('check')}<strong>Before you leave</strong><span>${activeChecks().filter(c=>c.done).length}/${activeChecks().length} ${AppI18n.locale==='ko'?'오늘의 준비물 완료 →':'day bag items ready →'}</span></button></div><p class="footnote">Travel mode follows your selected day and stop. Arrival estimates require a connected routing service.</p>`}

render();setInterval(()=>{if(view==='tools')updateClock()},60000);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_travel_plan',description:'Read the selected trip and day saved on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('Provide an empty object.');return{trip:trip().name,day:day+1,stops:stops().map(s=>({...s,name:place(s.place).name}))}}} ,{name:'select_travel_day',description:'Select a trip day and show its itinerary and map.',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1}},required:['day'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='day')||!Number.isInteger(input.day)||input.day<1||input.day>trip().days.length)throw Error('Choose a day within this trip.');day=input.day-1;view='plan';render();return{day:day+1,places:stops().length}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
